#include <string>

class Solution {
public:
    std::string removeOuterParentheses(std::string s) {
        std::string result;
        result.reserve(s.size());
        int balance = 0;
        for (char c : s) {
            if (c == '(') {
                if (balance > 0) {
                    result += c;
                }
                balance++;
            } else {
                balance--;
                if (balance > 0) {
                    result += c;
                }
            }
        }
        return result;
    }
};
